import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

// 업무영역 구분 값은 개발 담당자가 정한다 (결정).
const VISIBLE_RESULTS = `
  SELECT '결재문서' AS area,
    d.approval_document_id AS "resourceId",
    d.title AS title,
    CAST(NULL AS varchar) AS "fileName",
    d.created_at AS created_at
  FROM approval_document d
  WHERE (position(lower(:keyword) in lower(d.title)) > 0
      OR position(lower(:keyword) in lower(COALESCE(d.body, ''))) > 0)
    AND (d.drafter_id = CAST(:userId AS bigint)
      OR (d.is_secret = false AND d.approval_status <> '기안'))
  UNION ALL
  SELECT '게시물' AS area,
    p.post_id AS "resourceId",
    p.title AS title,
    CAST(NULL AS varchar) AS "fileName",
    p.created_at AS created_at
  FROM post p
  WHERE (position(lower(:keyword) in lower(p.title)) > 0
      OR position(lower(:keyword) in lower(p.content)) > 0)
    AND (p.author_id = CAST(:userId AS bigint)
      OR p.visibility_scope = 'ALL'
      OR (p.visibility_scope = 'DEPARTMENT'
        AND EXISTS (
          SELECT 1 FROM employee a
          WHERE a.employee_id = p.author_id
            AND a.department_id IS NOT NULL
            AND a.department_id = (
              SELECT me.department_id FROM employee me
              WHERE me.employee_id = CAST(:userId AS bigint)))))
  UNION ALL
  SELECT '첨부파일' AS area,
    t.attachment_id AS "resourceId",
    t.file_name AS title,
    t.file_name AS "fileName",
    t.created_at AS created_at
  FROM attachment t
  WHERE position(lower(:keyword) in lower(t.file_name)) > 0
    AND t.uploader_id = CAST(:userId AS bigint)
`;

@Controller('api/v1')
export class FnSfr04010Controller {
  @Get('/search-results')
  async searchIntegrated2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);

    const rawKeyword = query['keyword'];
    const keyword = typeof rawKeyword === 'string' ? rawKeyword.trim() : '';
    if (keyword === '') {
      throw new ApiError(422, 'SEARCH_KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }

    const rawPage = query['page'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page는 0 이상의 정수여야 합니다.');
    }
    const rawSize = query['size'];
    const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상의 정수여야 합니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);

    return transaction(async (db) => {
      const items = await db.query(
        'WITH r AS (' + VISIBLE_RESULTS + ')'
          + ' SELECT area, "resourceId", title, "fileName" FROM r'
          + ' ORDER BY created_at DESC, area, "resourceId"'
          + ' LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { keyword, userId: user.id, size: pageSize, offset: page * pageSize },
      );
      const totals = await db.query(
        'WITH r AS (' + VISIBLE_RESULTS + ')'
          + ' SELECT COUNT(*) AS total FROM r',
        { keyword, userId: user.id },
      );
      return {
        items,
        page,
        size: pageSize,
        total: Number(totals[0]?.total ?? 0),
      };
    });
  }
}

