import { useState } from 'react';
import { Band, DataTable, Drawer, ErrorText, Field, Filters, Pager, Pairs, TextInput, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr04010Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [guide, setGuide] = useState('검색어를 입력해 주세요.');
  const [selected, setSelected] = useState<Row | null>(null);

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (applied === '') {
      return undefined;
    }
    return call<Page>('GET', '/search-results', role, undefined, { keyword: applied, page, size: SIZE });
  }, [applied, page, role]);

  const search = () => {
    const text = keyword.trim();
    if (text === '') {
      setGuide('검색어를 입력해 주세요.');
      setApplied('');
      return;
    }
    setGuide('');
    setPage(0);
    setApplied(text);
  };

  const reset = () => {
    setKeyword('');
    setApplied('');
    setPage(0);
    setGuide('검색어를 입력해 주세요.');
  };

  const total = data ? data.total : 0;

  return (
    <div className="bento">
      <section className="box span-8">
        <h2>통합검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색 키워드" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="제목·내용·파일명" />
          </Field>
        </Filters>
        {guide !== '' && <ErrorText text={guide} />}
        {error !== '' && <ErrorText text={error} />}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'area', label: '업무영역 구분' },
            { key: 'title', label: '결과 제목' },
            { key: 'fileName', label: '파일명' },
          ]}
          rows={data ? data.items : []}
          onRowClick={(row) => setSelected(row)}
          empty={loading ? '검색 중입니다.' : applied === '' ? '검색어를 입력해 주세요.' : '검색 결과가 없습니다.'}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>검색 결과</h2>
        <p>{total}건</p>
      </section>
      {selected && (
        <Drawer title="검색 결과 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['업무영역 구분', String(selected['area'] ?? '')],
              ['결과 대상 ID', String(selected['resourceId'] ?? '')],
              ['결과 제목', String(selected['title'] ?? '')],
              ['파일명', String(selected['fileName'] ?? '')],
            ]}
          />
        </Drawer>
      )}
    </div>
  );
}
